package com.muthumol.player.dummy;
import java.net.*;import java.io.*;import java.util.*;import java.util.regex.*;import org.json.*;
/** Uses only the official public MSone addon, discovered from its install page. */
final class MsoneSubtitles {
 static final String ROOT="https://addon.malayalamsubtitles.org/";
 static final class Result{final String name;final byte[] bytes;Result(String n,byte[] b){name=n;bytes=b;}}
 static Result find(Movie movie)throws Exception{MediaTitle t=MediaTitle.parse(movie.title);String imdb=imdb(t);if(imdb.isEmpty())throw new IOException("MSone title could not be identified");String landing=new String(fetch(ROOT,512*1024),"UTF-8"),manifest="";if(landing.trim().startsWith("{"))manifest=ROOT;else{Matcher m=Pattern.compile("(?:https?://|stremio://)addon\\.malayalamsubtitles\\.org/[^\\s\"'<>]*manifest\\.json").matcher(landing.replace("&amp;","&"));if(m.find())manifest=m.group().replaceFirst("^stremio:","https:");}if(manifest.isEmpty())throw new IOException("MSone addon configuration unavailable");JSONObject config=new JSONObject(new String(fetch(manifest,512*1024),"UTF-8"));if(!config.has("resources"))throw new IOException("MSone manifest unavailable");String base=manifest.substring(0,manifest.lastIndexOf('/')+1),id=imdb+(t.episodic()?":"+t.season+":"+t.episode:"");JSONObject response=new JSONObject(new String(fetch(base+"subtitles/"+(t.episodic()?"series":"movie")+"/"+URLEncoder.encode(id,"UTF-8")+".json",1024*1024),"UTF-8"));JSONArray subtitles=response.optJSONArray("subtitles");if(subtitles==null)return null;for(int i=0;i<subtitles.length();i++){JSONObject sub=subtitles.getJSONObject(i);String lang=sub.optString("lang");if(!lang.equals("mal")&&!lang.equals("ml"))continue;String url=sub.optString("url"),path=new URL(url).getPath();String name=path.substring(path.lastIndexOf('/')+1);if(!AutoSubtitles.subtitle(name)&&!name.endsWith(".zip"))name="MSone.srt";return new Result(name,fetch(url,16*1024*1024));}return null;}
 static String imdb(MediaTitle t)throws Exception{if(t.episodic()){JSONArray results=new JSONArray(new String(ArtworkStore.fetch("https://api.tvmaze.com/search/shows?q="+ArtworkStore.enc(t.name),512*1024),"UTF-8"));JSONObject show=ArtworkStore.pickShow(t,results);if(show!=null){String date=show.optString("premiered");if(t.year>0&&!date.startsWith(""+t.year))return "";JSONObject external=show.optJSONObject("externals");return external==null?"":external.optString("imdb","");}return "";}String q=t.name+(t.year>0?" "+t.year:"")+" film";JSONObject response=new JSONObject(new String(ArtworkStore.fetch("https://en.wikipedia.org/w/api.php?action=query&format=json&formatversion=2&generator=search&gsrsearch="+ArtworkStore.enc(q)+"&gsrlimit=5&prop=extlinks%7Cextracts&exintro=1&explaintext=1&exchars=250&ellimit=20&elquery=imdb.com%2Ftitle%2F",512*1024),"UTF-8"));JSONObject query=response.optJSONObject("query");JSONArray pages=query==null?null:query.optJSONArray("pages");if(pages!=null)for(int i=0;i<pages.length();i++){JSONObject page=pages.getJSONObject(i);String name=page.optString("title");if(MediaTitle.similarity(t.name,name.replaceAll("\\s*\\([^)]*\\)",""))<.85||t.year>0&&!name.contains(""+t.year)&&!page.optString("extract").contains(""+t.year))continue;JSONArray links=page.optJSONArray("extlinks");if(links==null)continue;for(int n=0;n<links.length();n++){Matcher match=Pattern.compile("imdb\\.com/title/(tt[0-9]+)").matcher(links.getJSONObject(n).optString("url"));if(match.find())return match.group(1);}}return "";}
 static boolean allowed(URL u){String host=u.getHost().toLowerCase(Locale.ROOT);return u.getProtocol().equals("https")&&(u.getPort()==-1||u.getPort()==443)&&u.getUserInfo()==null&&(host.equals("malayalamsubtitles.org")||host.endsWith(".malayalamsubtitles.org"));}
 static byte[] fetch(String raw,int limit)throws Exception{URL u=new URL(raw);for(int redirect=0;redirect<4;redirect++){if(!allowed(u))throw new IOException("Untrusted subtitle host");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(5000);c.setReadTimeout(8000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","TGstream/6.1");try{int code=c.getResponseCode();if(code>=300&&code<400){u=new URL(u,c.getHeaderField("Location"));continue;}if(code!=200)throw new IOException("MSone unavailable (HTTP "+code+")");if(c.getContentLength()>limit)throw new IOException("Subtitle response too large");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>limit)throw new IOException("Subtitle response too large");out.write(buffer,0,n);}return out.toByteArray();}}finally{c.disconnect();}}throw new IOException("Too many subtitle redirects");}
}
